<?php
if(!defined('ABSPATH'))exit;
add_action('admin_menu',static function(){add_submenu_page('sr-academy-lms','Razorpay payments','Payments','manage_options','sr-lms-payments','sr_lms_payment_admin');});
function sr_lms_payment_admin(): void {
 if(!current_user_can('manage_options'))return;$s=sr_lms_payment_settings();$notice='';
 if($_SERVER['REQUEST_METHOD']==='POST'){
  check_admin_referer('sr_lms_payments');
  foreach($_POST as $name=>$value){if($name==='offers'){if(!is_array($value)||count(array_filter($value,'is_string'))!==count($value))wp_die('Invalid offers.','Invalid settings',['response'=>400]);}elseif(!is_string($value))wp_die('Invalid settings field.','Invalid settings',['response'=>400]);}
  if(isset($_POST['reconcile'])){$r=sr_lms_payment_reconcile(absint($_POST['reconcile']));$notice=is_wp_error($r)?$r->get_error_message():'Payment reconciled.';}
  else {
   $next=$s;$next['offers']=array_values(array_intersect(array_keys(sr_lms_offers()),array_map('sanitize_key',(array)($_POST['offers']??[]))));$next['enabled']=empty($_POST['enabled'])?0:1;$next['manual_requests']=empty($_POST['manual_requests'])?0:1;$next['mode']=in_array($_POST['mode']??'',['test','live'],true)?$_POST['mode']:'test';$valid=true;
   foreach(['test','live'] as $mode){$key=sanitize_text_field(wp_unslash($_POST[$mode.'_key']??''));if($key!==''&&!preg_match('/^rzp_'.$mode.'_[A-Za-z0-9]+$/D',$key)){$valid=false;$notice='Invalid '.$mode.' key ID.';}else $next[$mode.'_key']=$key;
    foreach(['secret','webhook'] as $field){$name=$mode.'_'.$field;$plain=trim(wp_unslash($_POST[$name]??''));if($plain!==''){$sealed=sr_lms_payment_encrypt($plain);if(is_wp_error($sealed)){$valid=false;$notice=$sealed->get_error_message();}else $next[$name]=$sealed;}if(!empty($_POST['clear_'.$name]))unset($next[$name]);}
   }
   global $wpdb;foreach(['test','live'] as $mode){$hasOrders=$wpdb->get_var($wpdb->prepare('SELECT id FROM '.sr_lms_table('payments').' WHERE mode=%s AND gateway_order IS NOT NULL LIMIT 1',$mode));if($hasOrders&&(($next[$mode.'_key']??'')!==($s[$mode.'_key']??'')||empty($next[$mode.'_secret'])||empty($next[$mode.'_webhook'])||(($next[$mode.'_webhook']??'')!==($s[$mode.'_webhook']??'')))){$valid=false;$notice='Saved orders bind this mode to its gateway key and webhook secret. Changing the key, clearing credentials, or rotating the webhook secret is blocked to preserve reconciliation. Restore the API secret for the same key if needed.';}}
   if($valid){update_option('sr_lms_payment_settings',$next,false);$s=$next;$notice='Settings saved.';}
  }
 }
 echo '<div class="wrap"><h1>SR Academy · Razorpay payments</h1>';if($notice)echo '<div class="notice notice-info"><p>'.esc_html($notice).'</p></div>';
 echo '<p>One-time INR payments. Test checkout records simulated purchases without granting course access. Live checkout grants access only after server verification of a captured payment. Configure automatic capture in the Razorpay dashboard.</p><form method="post">';wp_nonce_field('sr_lms_payments');
 echo '<p><label><input type="checkbox" name="enabled" value="1" '.checked(!empty($s['enabled']),true,false).'> Enable checkout</label></p><p><label><input type="checkbox" name="manual_requests" value="1" '.checked(sr_lms_manual_requests_enabled(),true,false).'> Allow manual enrollment requests</label></p><p><label>Checkout mode <select name="mode"><option value="test" '.selected($s['mode']??'test','test',false).'>Test</option><option value="live" '.selected($s['mode']??'test','live',false).'>Live</option></select></label></p>';
 echo '<h2>Offers available for online purchase</h2><p>Only selected offers can create gateway orders. Confirm recordings and prices before enabling an offer. Existing order prices remain fixed.</p>';foreach(sr_lms_offers() as $slug=>$offer){echo '<p><label><input type="checkbox" name="offers[]" value="'.esc_attr($slug).'" '.checked(in_array($slug,(array)($s['offers']??[]),true),true,false).'> '.esc_html($offer['title']).' · INR '.esc_html(number_format($offer['price'],2)).'</label></p>';}
 foreach(['test','live'] as $mode){echo '<h2>'.esc_html(ucfirst($mode)).' credentials</h2><p>Webhook: <code>'.esc_html(rest_url('sr-lms/v1/payments/webhook/'.$mode)).'</code></p><p>Subscribe to payment.captured and refund.processed. Webhooks require a public HTTPS address; local sites cannot receive them.</p><p><label>Key ID <input autocomplete="off" name="'.esc_attr($mode.'_key').'" value="'.esc_attr($s[$mode.'_key']??'').'"></label></p>';
 foreach(['secret'=>'API secret','webhook'=>'Webhook signing secret'] as $field=>$label){$name=$mode.'_'.$field;echo '<p><label>'.esc_html($label).' <input type="password" autocomplete="new-password" name="'.esc_attr($name).'" value="" placeholder="'.(!empty($s[$name])?'Saved · blank keeps existing':'Not configured').'"></label> <label><input type="checkbox" name="clear_'.esc_attr($name).'" value="1"> Clear saved secret</label></p>';}}
 submit_button('Save payment settings');echo '</form><p>Secrets are encrypted with the WordPress auth salt. Changing salts requires entering credentials again. Gateway key IDs and webhook secrets cannot change while that mode has recorded orders. API secrets may be restored for the same key after a salt change. Receipt status in history shows sent or pending; reconcile retries failed receipts. No refunds are issued here; process them in Razorpay, then reconcile.</p><h2>Recent payment history</h2><table class="widefat striped"><thead><tr><th>Order</th><th>Student / offer</th><th>Mode / amount</th><th>State</th><th>Gateway references</th><th>Retry</th></tr></thead><tbody>';
 global $wpdb;$rows=$wpdb->get_results('SELECT * FROM '.sr_lms_table('payments').' ORDER BY id DESC LIMIT 100',ARRAY_A);
 foreach($rows as $row){echo '<tr><td>'.(int)$row['id'].'<br>'.esc_html($row['created_at']).'</td><td>'.(int)$row['user_id'].' / '.esc_html($row['offer']).'</td><td>'.esc_html($row['mode']).' / INR '.esc_html(number_format($row['amount']/100,2)).'</td><td>'.esc_html($row['status']).'<br>Receipt: '.($row['email_sent']==1?'sent':($row['mode']==='test'?'not sent (test)':'pending / retry')).'<br>Refunded INR '.esc_html(number_format($row['refunded']/100,2)).'</td><td>'.esc_html($row['gateway_order']??'').'<br>'.esc_html($row['gateway_payment']??'').'</td><td><form method="post">';wp_nonce_field('sr_lms_payments');echo '<button class="button" name="reconcile" value="'.(int)$row['id'].'">Reconcile</button></form></td></tr>';}
 echo '</tbody></table></div>';
}
